import calendar
from datetime import date, timedelta
from itertools import islice

_WD = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def _daily(s, k):
    d = s
    while True:
        yield d
        d += timedelta(days=k)


def _weekly(s, k, days):
    monday = s - timedelta(days=s.weekday())
    idx = sorted(_WD[x] for x in days)
    j = 0
    while True:
        base = monday + timedelta(weeks=j * k)
        for w in idx:
            d = base + timedelta(days=w)
            if d >= s:
                yield d
        j += 1


def _monthly(s, k, pick):
    base = s.year * 12 + s.month - 1
    j = 0
    while True:
        y, m = divmod(base + j * k, 12)
        m += 1
        for d in pick(y, m):
            if d >= s:
                yield d
        j += 1


def _yearly(s, k, mm, dd):
    j = 0
    while True:
        y = s.year + j * k
        try:
            d = date(y, mm, dd)
        except ValueError:
            d = None
        if d is not None and d >= s:
            yield d
        j += 1


def recur(start: str, rule: str, count: int) -> list[str]:
    s = date.fromisoformat(start)
    parts = rule.split(" ")
    kind = parts[0]

    if kind == "DAILY":
        gen = _daily(s, int(parts[1]))

    elif kind == "WEEKLY":
        gen = _weekly(s, int(parts[1]), parts[2].split(","))

    elif kind == "MONTHLY" and len(parts) == 3:
        k = int(parts[1])
        D = int(parts[2])

        def pick(y, m):
            n = calendar.monthrange(y, m)[1]
            day = n if D == -1 else D
            return [date(y, m, day)] if day <= n else []

        gen = _monthly(s, k, pick)

    elif kind == "MONTHLY":
        k = int(parts[1])
        N = int(parts[2])
        wd = _WD[parts[3]]

        def pick(y, m):
            n = calendar.monthrange(y, m)[1]
            if N > 0:
                first = date(y, m, 1)
                off = (wd - first.weekday()) % 7
                d = 1 + off + 7 * (N - 1)
                return [date(y, m, d)] if d <= n else []
            last = date(y, m, n)
            off = (last.weekday() - wd) % 7
            return [date(y, m, n - off)]

        gen = _monthly(s, k, pick)

    else:  # YEARLY
        k = int(parts[1])
        mm, dd = (int(x) for x in parts[2].split("-"))
        gen = _yearly(s, k, mm, dd)

    return [d.isoformat() for d in islice(gen, count)]
